pub struct AppleDispatcher;

#[cfg(target_os = "macos")]
static TERMINATION_RUN_LOOP: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

#[cfg(target_os = "macos")]
fn dispatch_termination_ready(context: *mut c_void) {
    use core_foundation::{runloop::{CFRunLoopGetMain, CFRunLoopRef, CFRunLoopWakeUp, kCFRunLoopCommonModes}, string::CFStringRef};
    unsafe extern "C" {
        fn CFRunLoopPerformBlock(run_loop: CFRunLoopRef, mode: CFStringRef, block: &block2::DynBlock<dyn Fn()>);
    }
    let block = block2::RcBlock::new(move || trampoline(context));
    // SAFETY: Core Foundation copies the block and executes it once on the main
    // run loop. The runnable's raw ownership is transferred once to trampoline,
    // exactly as with exec_async_f. No App/entity borrow is captured. Common modes
    // remain serviceable inside AppKit's deferred should-terminate loop.
    unsafe {
        let run_loop = CFRunLoopGetMain();
        CFRunLoopPerformBlock(run_loop, kCFRunLoopCommonModes, &block);
        CFRunLoopWakeUp(run_loop);
    }
}

impl AppleDispatcher {
    /// Enable common-run-loop wakes before installing the macOS termination
    /// owner. Keep this enabled, including before requests, so previously queued
    /// foreground work cannot be stranded behind a nested terminate call.
    #[cfg(target_os = "macos")]
    pub fn enable_termination_run_loop() {
        TERMINATION_RUN_LOOP.store(true, std::sync::atomic::Ordering::Release);
    }

    pub fn new() -> Self {

fn dispatch_on_main_thread(&self, runnable: RunnableVariant, _priority: Priority) {
    let context = runnable.into_raw().as_ptr() as *mut c_void;
    #[cfg(target_os = "macos")]
    if TERMINATION_RUN_LOOP.load(std::sync::atomic::Ordering::Acquire) {
        dispatch_termination_ready(context);
        return;
    }
